/*
 * form.js -- the contract's own description of a request, as controls.
 *
 * GENERATED by nothing; this is the renderer that reads what apigen
 * generates (ADR-0338, #595). It is its own file for one reason: it has
 * no dependency on the dashboard at all beyond `document` and
 * `CIX_API`, which means a test can EXECUTE it rather than only parse
 * it -- `test_web_form` evals this file against a minimal DOM and
 * asserts that a `format: password` field really does produce an
 * obscured input, that an enum really does produce its own options, and
 * that an empty optional field really is omitted from the body.
 *
 * Keeping it inside app.js would have made that impossible: evaluating
 * that file runs a dashboard's worth of module-level wiring against
 * hundreds of element ids, so the only check it can ever have is that
 * it parses -- which is exactly the gap that let three unparseable
 * api.js releases through (#594).
 *
 * app.js owns the SUBMIT listener, and only that, because it is an HTTP
 * request and a status line and neither can be stubbed meaningfully.
 *
 * What this file expects app.js to have defined, which is the whole of
 * its dependency on the dashboard and is deliberately short enough to
 * stub in a test: `openModal`, `sessionMay`, `sessionRefusal`,
 * `showStatus`, `runRefreshers`, `refreshersForView`,
 * `qualifyHostname`, and -- for `renderTable` -- `statusBadge`,
 * `treeLink`, `listState`, `listSignature` and
 * `unchangedAndRendered`. `qualifyHostname` is site knowledge (what
 * this host's own domain is); the last five are the dashboard's own
 * status vocabulary, its link shape and its repaint guard, all of
 * which already exist in one place each and must not be forked here.
 */
/*
 * ---------- what a request schema becomes ----------
 *
 * One modal panel, built from the operation's own request schema, for
 * every create and edit the dashboard offers.
 *
 * The 36 hand-written forms this replaces re-typed what the contract
 * already states -- field names, types, which are required, which
 * values an enum allows -- and dropped what it states that is hardest
 * to re-type: 174 constraints, which reached the operator as a
 * round-trip 400 instead of as a form that would not submit. So the
 * split is ADR-0338's sixth principle exactly. GENERATED, because two
 * competent people would write it identically from the schema: the
 * fields, their order, their controls, their bounds, their hints.
 * AUTHORED at the call site, because it takes judgement: the modal's
 * title, the three words on its button, which resource list to refresh
 * afterwards, and what to say when it fails.
 *
 * A field's rendering is decided by the field, never by its name -- a
 * `name === "password"` special case here would be the parallel the
 * guidelines forbid, and is why the eight secrets an operator TYPES
 * carry `format: password` in the contract instead.
 */

/*
 * THE OPERATOR'S WORD FOR A FIELD, which is the contract's `title`.
 *
 * The fallback de-cases the schema key, and that is all it can do:
 * `sn` becomes "Sn", `ip` becomes "Ip", `uidnumber` becomes
 * "Uidnumber". Those are real renders from a real form and they are
 * the dashboard speaking its own schema's vocabulary at a person --
 * what web-ux-guidelines' fifth principle exists to forbid. So the
 * fallback is a LAST RESORT and not the design: the Primitives board
 * puts the rule in one line, *"a label that needs to differ goes in
 * the contract, not in app.js"*, and JSON Schema's own `title` is
 * where it goes.
 *
 * It still takes a bare name as well as a field, because the modal's
 * own heading falls back to the operation id when no title is
 * authored at the call site.
 */
function fieldLabel(f) {
	const name = typeof f === "string" ? f : f.name;
	const words = name.replace(/_/g, " ");

	if (typeof f === "object" && f.title)
		return f.title;
	return words.charAt(0).toUpperCase() + words.slice(1);
}

/*
 * THE CONSTRAINT, IN THE OPERATOR'S SIGHT RATHER THAN ONLY IN THE
 * INPUT -- the monospace chip the Generated board puts to the right of
 * every label (`1-15 · [A-Za-z0-9-]`, `8 - 30`).
 *
 * Derived entirely, because every part of it is already a fact of the
 * schema. The point is not decoration: a `pattern` that silently
 * refuses a keystroke is worse than one the operator can read, and
 * until this existed the contract's 174 constraints were invisible
 * until the form would not submit.
 *
 * A pattern is shown as its CHARACTER CLASS rather than as the regex,
 * because `^[A-Za-z0-9_\-]+$` is not a thing to put in front of
 * someone. Where that cannot be extracted the pattern is not shown at
 * all -- an unreadable chip is worse than no chip, and the hint still
 * carries the rule in words.
 */
function constraintText(f) {
	const parts = [];
	const lo = f.minimum !== undefined;
	const hi = f.maximum !== undefined;
	let cls = null;

	if (lo && hi)
		parts.push(f.minimum + " – " + f.maximum);
	else if (lo)
		parts.push("≥ " + f.minimum);
	else if (hi)
		parts.push("≤ " + f.maximum);

	if (f.pattern !== undefined) {
		/*
		 * The END-anchored class first, then the first class as a
		 * fallback. Two real shapes in this contract need both:
		 * `^[a-z_][a-z0-9_\-]*$` leads with a one-character anchor
		 * class and the meaningful one is at the end, while a
		 * hostname's `^[A-Za-z0-9\-]{1,63}(\.…)*$` ends inside a
		 * group and the meaningful one is first. `\-` reads as `-`,
		 * since that spelling is for the regex engine and not for a
		 * person.
		 */
		const m = /\[([^\]]+)\](\{(\d+),(\d+)\})?[+*]?\$?$/.exec(f.pattern) ||
			/\[([^\]]+)\](\{(\d+),(\d+)\})?/.exec(f.pattern);

		if (m !== null) {
			cls = "[" + m[1].replace(/\\-/g, "-") + "]";
			if (m[3] !== undefined)
				parts.push(m[3] + "–" + m[4]);
		}
	}
	if (f.maxLength !== undefined && f.pattern === undefined)
		parts.push("≤ " + f.maxLength + " chars");
	if (cls !== null)
		parts.push(cls);
	/*
	 * A standard `format`, in words, when nothing numeric was derived
	 * -- the board's chip for `subnet` is "dotted quad", which is what
	 * `format: ipv4` means to a person. The map is RENDERING, the same
	 * kind of decision as `format: password` producing an obscured
	 * input; the fact itself stays in the contract.
	 */
	if (parts.length === 0 && f.format !== undefined && FORMAT_WORD[f.format] !== undefined)
		parts.push(FORMAT_WORD[f.format]);
	/* A map's shape is the one thing about it the operator must know
	 * before typing, and nothing else in the form says it. */
	if (parts.length === 0 && isStringMap(f))
		parts.push("KEY=VALUE per line");
	if (parts.length === 0 && f.ui === "lines")
		parts.push("one per line");
	return parts.join(" · ");
}

const FORMAT_WORD = {
	ipv4: "dotted quad",
	ipv6: "IPv6",
	hostname: "hostname",
	"date-time": "RFC 3339",
	uri: "URL",
	email: "email",
	byte: "base64",
};

/*
 * ONE SENTENCE, not the reference paragraph.
 *
 * The contract's `description` is API documentation -- 214 characters
 * on average, up to 2,064 -- and rendering it under every input turns
 * a four-field form into a wall of prose. Clamping it to three lines
 * was the first attempt and it was wrong: it hid the symptom and left
 * a sentence cut mid-word.
 *
 * Measured across this contract on 2026-10-10: of 684 property
 * descriptions, 89% have a first sentence that works as a hint on its
 * own, mean 81 characters. So the first sentence IS the hint, the
 * whole description stays on the label's `title` for hover, and the
 * convention that follows is a writing rule rather than a second key:
 * **the first sentence of a property description is what an operator
 * needs; everything after it is reference detail.** The 11% that do
 * not comply are a contract fix, and `test_apigen` names them.
 *
 * An abbreviation is why this is not a bare split on ". " -- "e.g. "
 * and "i.e. " end no sentence, and the contract uses both. A scan
 * rather than a regex with a sentinel: the sentinel version of this
 * function wrote two literal NUL bytes into this file, which git saw
 * as a binary change.
 */
const HINT_ABBREV = ["e.g.", "i.e.", "cf.", "vs.", "approx.", "etc."];

function fieldHint(f) {
	if (f.description === undefined)
		return "";
	const text = f.description.replace(/\s+/g, " ").trim();
	let at = 0;

	for (;;) {
		const dot = text.indexOf(". ", at);

		if (dot < 0)
			return text;
		const upto = text.slice(0, dot + 1);
		let abbrev = false;

		for (const a of HINT_ABBREV)
			if (upto.endsWith(a))
				abbrev = true;
		if (!abbrev)
			return upto;
		at = dot + 2;
	}
}

/*
 * The one control a field's constraints describe.
 *
 * Every branch is a property of the schema and nothing else: options
 * make a select, boolean a checkbox, a numeric type a number input
 * carrying its own minimum and maximum, `format: password` an obscured
 * input, and a string its pattern and maxLength. An array of scalars is
 * a comma-separated text input, the convention the hand-written
 * container form already used for `dns_servers`.
 */
function fieldControl(f, choices) {
	let el;

	/*
	 * CHOICES FROM THE BOX FIRST (#592): a select of the things that
	 * really exist -- the host's disks, its networks, its registered
	 * DHCP servers -- where the contract can only say "a string".
	 *
	 * Authored at the call site, not derived, because WHICH list and
	 * how it is filtered is the page's judgement: a disk already given a
	 * role is not a candidate for another, and the contract has no way
	 * to say so. What is derived is the control: an array field's
	 * choices are a multiple select, because an array is the contract
	 * saying "any number of these".
	 *
	 * An empty list is a select offering nothing rather than a free
	 * text input, since a value the page could not find is one the
	 * daemon would refuse -- and a required one then cannot submit,
	 * which is the truth about it.
	 */
	if (Array.isArray(choices)) {
		el = document.createElement("select");
		if (f.type === "array") {
			el.multiple = true;
			el.size = Math.min(Math.max(choices.length, 2), 6);
		} else if (!f.required || f.nullable || choices.length === 0) {
			const blank = document.createElement("option");

			blank.value = "";
			blank.textContent = choices.length === 0 ? "None available" : "—";
			el.appendChild(blank);
		}
		for (const c of choices) {
			const o = document.createElement("option");

			o.value = c.value;
			o.textContent = c.label !== undefined ? c.label : c.value;
			el.appendChild(o);
		}
	}

	/*
	 * `ui` FIRST, because it is the contract overriding a derivation
	 * it has already judged wrong (ADR-0338) -- a derived control that
	 * won over an explicit one would make the override unreliable in
	 * exactly the cases it exists for.
	 *
	 * Only `textarea` is known, and nothing else can reach here:
	 * apigen refuses any other value of `x-cix-ui` at generation,
	 * because a control this function does not know would fall through
	 * to a plain text input and be silently wrong. The refusal belongs
	 * there rather than in a throw here, which would take a form down
	 * in a browser over a contract typo.
	 *
	 * An `object` field needs no annotation and gets one anyway: a
	 * free-form object (`additionalProperties`, so the contract names
	 * no properties to render) is typed as JSON, and a one-line text
	 * input is never the right control for JSON. That is DERIVED,
	 * which is the rule -- `x-cix-ui` exists for the string case,
	 * where the schema really does say nothing.
	 *
	 * The row counts are the one judgement here: a document field
	 * holds a recipe (the hand-written forms it replaces used 10 and
	 * 16), a JSON object field holds a handful of keys (they used 3
	 * and 6). `resize: vertical` means neither is a ceiling.
	 */
	if (Array.isArray(choices)) {
		/* Built above; the shared tail below still applies. */
	} else if (f.ui === "tristate") {
		/*
		 * A BOOLEAN WITH A DEFAULT THE FORM CANNOT KNOW (#592). A
		 * checkbox has two states and this field has three: on, off,
		 * and "absent", which the daemon resolves from its own
		 * setting -- `userns` is ON on a fresh host. An unticked box
		 * would send false and switch isolation off for every
		 * container made from this form.
		 */
		el = document.createElement("select");
		for (const [v, t] of [["", "Host default"], ["true", "On"], ["false", "Off"]]) {
			const o = document.createElement("option");

			o.value = v;
			o.textContent = t;
			el.appendChild(o);
		}
	} else if (f.ui === "bytes") {
		/*
		 * A SIZE, typed with its unit (#592). The contract's unit is
		 * the byte, which is right for the wire and wrong for a person:
		 * the volume quota form used to take GiB and multiply, and a
		 * memory limit typed as 1073741824 is a typo waiting to happen.
		 * The unit is the form's business and never reaches the body --
		 * the value is sent in bytes, exactly as the contract says.
		 * The unit select is attached beside the input by buildFields().
		 */
		const unit = document.createElement("select");

		el = document.createElement("input");
		el.type = "number";
		el.min = "0";
		el.step = "any";
		for (const [v, t] of BYTE_UNITS) {
			const o = document.createElement("option");

			o.value = String(v);
			o.textContent = t;
			unit.appendChild(o);
		}
		unit.value = String(1024 * 1024 * 1024);
		unit.className = "field-unit";
		el._cixUnit = unit;
	} else if (f.ui === "lines") {
		/* An argv, one argument per line (#592): a comma list cannot
		 * carry `-o a,b`, and an argument is the unit the operator
		 * reads a command in. */
		el = document.createElement("textarea");
		el.rows = 3;
		el.spellcheck = false;
	} else if (isStringMap(f)) {
		/*
		 * A MAP OF STRINGS (#592) -- `additionalProperties: {type:
		 * string}`, which apigen records as `items: "string"` on an
		 * object. KEY=VALUE, one per line, which is how every one of
		 * them is written outside a form: modprobe options, an
		 * environment, sysctls. JSON was correct and nobody types
		 * `{"debug": "1"}` to load a module.
		 */
		el = document.createElement("textarea");
		el.rows = 4;
		el.spellcheck = false;
		el.placeholder = "KEY=VALUE";
	} else if (f.ui === "textarea" || f.type === "object") {
		el = document.createElement("textarea");
		el.rows = f.type === "object" ? 6 : 12;
		el.spellcheck = false;
		if (f.maxLength !== undefined)
			el.maxLength = f.maxLength;
	} else if (Array.isArray(f.options) && f.options.length > 0) {
		el = document.createElement("select");
		if (!f.required || f.nullable) {
			const blank = document.createElement("option");

			blank.value = "";
			/* The blank sends nothing, so the daemon's own default
			 * applies -- and when the contract says what that is, the
			 * choice says so rather than a bare dash. */
			blank.textContent = f.fallback !== undefined ? "Default (" + f.fallback + ")" : "—";
			el.appendChild(blank);
		}
		for (const opt of f.options) {
			const o = document.createElement("option");

			o.value = opt;
			o.textContent = opt;
			el.appendChild(o);
		}
	} else if (f.type === "boolean") {
		el = document.createElement("input");
		el.type = "checkbox";
		if (f.fallback === true)
			el.checked = true;
	} else if (f.type === "integer" || f.type === "number") {
		el = document.createElement("input");
		el.type = "number";
		if (f.minimum !== undefined)
			el.min = String(f.minimum);
		if (f.maximum !== undefined)
			el.max = String(f.maximum);
		if (f.type === "integer")
			el.step = "1";
	} else {
		el = document.createElement("input");
		el.type = f.format === "password" ? "password" : "text";
		if (f.pattern !== undefined)
			el.pattern = f.pattern;
		if (f.maxLength !== undefined)
			el.maxLength = f.maxLength;
		/*
		 * `format: hostname` -- OpenAPI's own standard format, read
		 * the same way `format: password` is, and it earns the
		 * dashboard's bare-label convenience: typing `db` leaves the
		 * field as `db.<site>.<domain>`.
		 *
		 * That used to be wired by hand onto two specific element ids
		 * (`df-name`, `pf-name`), which is why only those two had it
		 * -- a convenience attached to an id rather than to a KIND OF
		 * FIELD cannot reach the next hostname field anyone adds. The
		 * site's own suffix is app.js's to know, so the behaviour is
		 * a global this file declares (see the header) rather than
		 * something derived here.
		 */
		if (f.format === "hostname")
			qualifyHostname(el);
	}
	/* What leaving it empty means, where the contract says: a restart
	 * delay of 2, a certificate directory of /etc/cix-tls (#592). */
	if (f.fallback !== undefined && f.type !== "boolean" && f.options === undefined &&
	    !Array.isArray(choices) && !el.placeholder)
		el.placeholder = String(f.fallback);
	el.id = "gf-" + f.name;
	el.dataset.field = f.name;
	el.dataset.ftype = f.type;
	if (f.ui !== undefined)
		el.dataset.ui = f.ui;
	/*
	 * An array's ITEM type, because a comma-separated list of digits
	 * is not a list of numbers until someone converts it (#596).
	 *
	 * `LdapUserCreateRequest.secondary_groups` is `items: integer`,
	 * and without this the body carried `["10001","10002"]` -- which
	 * the daemon reads with json_as_number() on a JSON string, so
	 * every gid would have arrived as 0 and the user would have been
	 * put in no secondary group at all. Found by rendering the real
	 * form and printing the body it collects, not by reading.
	 */
	if ((f.type === "array" || f.type === "object") && f.items !== undefined)
		el.dataset.fitems = f.items;
	/* A multiple select's `required` means "at least one", which an
	 * array the contract marks required does mean -- but an optional
	 * one must be submittable with nothing chosen.
	 *
	 * A NULLABLE field is never browser-required, even when the
	 * contract requires the key (#592): its empty value is `null`, and
	 * null is often the point -- a volume's owner left empty is root,
	 * a storage migration to no disk is "the default placement". The
	 * browser would refuse the empty field the operator meant. */
	if (f.nullable)
		el.dataset.nullable = "1";
	/* Recorded apart from the attribute, because a nullable required
	 * field drops the attribute and must still be sent. */
	if (f.required)
		el.dataset.required = "1";
	/* Nor is an ARRAY: a required array is a key that must be sent, not
	 * a list that may not be empty -- DNS forwarders cleared is a
	 * setting, "authoritative-only". The collector sends [] for it. */
	if (f.required && f.type !== "boolean" && f.type !== "array" && !f.nullable)
		el.required = true;
	return el;
}

/* The units a size is typed in, largest first, so a stored size is
 * shown in the largest unit that divides it exactly. */
const BYTE_UNITS = [
	[1024 * 1024 * 1024 * 1024, "TiB"],
	[1024 * 1024 * 1024, "GiB"],
	[1024 * 1024, "MiB"],
	[1024, "KiB"],
	[1, "bytes"],
];

/* An object whose values the contract types as strings: a map, not a
 * document. */
function isStringMap(f) {
	return f.type === "object" && f.items === "string";
}

/*
 * KEY=VALUE lines into the object they mean, and back.
 *
 * Split at the FIRST `=`, because a value may itself contain one (a
 * kernel command-line fragment, a base64 secret's padding) and a key
 * never does. A line with no `=`, or the same key twice, is refused
 * rather than guessed at: the first is a typo, and the second would
 * silently drop one of the two values the operator wrote.
 */
function parseStringMap(label, text) {
	const out = {};

	for (const raw of text.split("\n")) {
		const line = raw.trim();
		const eq = line.indexOf("=");
		let key;

		if (line === "")
			continue;
		if (eq <= 0)
			throw new Error(label + ": \"" + line + "\" is not KEY=VALUE");
		key = line.slice(0, eq).trim();
		if (Object.prototype.hasOwnProperty.call(out, key))
			throw new Error(label + ": " + key + " is given twice");
		out[key] = line.slice(eq + 1).trim();
	}
	return out;
}

function stringMapText(map) {
	return Object.keys(map).map((k) => k + "=" + map[k]).join("\n");
}

/*
 * What the operator typed, as the request body the schema describes.
 *
 * An empty optional field is OMITTED rather than sent as "", because
 * every partial-update endpoint in this API reads an absent key as
 * "leave it alone" and an empty string as "set it to empty" -- sending
 * the second for the first is how a generated form would quietly clear
 * a field nobody touched.
 */
function generatedFormBody(form) {
	const body = {};
	const cleared = {};

	/* A kept secret's "Clear" box (#592): checked, the secret is sent
	 * as "" -- the one way to say "remove it" when an empty field
	 * already means "keep it". */
	for (const box of form.querySelectorAll("[data-clear-for]"))
		if (box.checked)
			cleared[box.dataset.clearFor] = true;
	collectInto(form, body, cleared, form._cix !== undefined && form._cix.changedOnly === true);
	return body;
}

/*
 * THE BODY IS A WALK, NOT A QUERY (#592).
 *
 * `querySelectorAll("[data-field]")` finds every field in the form, at
 * any depth -- which was right while a form was flat and is wrong the
 * moment one holds a group (a DNS server role's hosts file) or rows (a
 * container's services): their fields would land in the top-level body
 * beside `name` and `image`. So the walk stops at a group or a list and
 * hands its subtree to the collector for that shape, which builds the
 * nested object or array and puts it under the field's own name.
 */
function collectInto(container, body, cleared, changedOnly) {
	for (const el of Array.from(container.children)) {
		if (el.dataset === undefined)
			continue;
		if (el.dataset.list !== undefined) {
			collectList(el, body);
			continue;
		}
		if (el.dataset.group !== undefined) {
			collectGroup(el, body);
			continue;
		}
		if (el.dataset.field !== undefined) {
			const name = el.dataset.field;

			readField(el, body, cleared);
			/* A partial update sends what the operator changed and
			 * nothing else (`changedOnly`, #592): a value sent back
			 * exactly as it was read is not "unchanged" to every
			 * daemon -- LDAP's listener settings, echoed back, take the
			 * listeners into the daemon's management for good. */
			if (changedOnly && el._cixStart !== undefined &&
			    JSON.stringify(body[name]) === el._cixStart)
				delete body[name];
			continue;
		}
		collectInto(el, body, cleared, changedOnly);
	}
}

/*
 * A list's rows, each collected as its own object. A required list
 * with no rows is refused, naming the field -- `services` is required
 * and at least one, and its form opens with a row for that reason.
 */
function collectList(fs, body) {
	const name = fs.dataset.list;
	const rows = Array.from(fs.children).find((c) => c.dataset !== undefined &&
	                                                c.dataset.rows !== undefined);
	const items = [];

	for (const row of rows === undefined ? [] : Array.from(rows.children)) {
		const item = {};

		if (row.dataset === undefined || row.dataset.item === undefined)
			continue;
		collectInto(row, item, {});
		items.push(item);
	}
	if (items.length === 0) {
		if (fs.dataset.required === "1")
			throw new Error(fieldLabel(fs.dataset.label || name) + " needs at least one");
		return;
	}
	body[name] = items;
}

/*
 * A group is sent only when something in it was filled -- a box left
 * unticked is not "something" -- and once it is sent, its own required
 * fields must be there. That is checked HERE rather than by the
 * browser, because an optional group's inputs carry no `required`: the
 * browser would refuse every submit that did not declare a DNS server
 * because the DNS server's hosts file was empty.
 */
function collectGroup(fs, body) {
	const name = fs.dataset.group;
	const label = fieldLabel(fs.dataset.label || name);
	const sub = {};

	collectInto(fs, sub, {});
	if (!Object.keys(sub).some((k) => sub[k] !== false && sub[k] !== null)) {
		if (fs.dataset.required === "1")
			throw new Error(label + " is required");
		return;
	}
	for (const f of CIX_API.FIELDS[fs.dataset.of] || [])
		if (f.required && !f.readOnly && sub[f.name] === undefined)
			throw new Error(label + ": " + fieldLabel(f) + " is required");
	body[name] = sub;
}

/* One control's value into the body under its field's name. */
function readField(el, body, cleared) {
	const name = el.dataset.field;
	const type = el.dataset.ftype;

	if (cleared[name]) {
		body[name] = "";
		return;
	}
	/* `tristate` (#592): a boolean whose absence means a default the
	 * form cannot know -- `userns` is ON by the host's own setting.
	 * "Default" sends nothing, so the host decides. */
	if (el.dataset.ui === "tristate") {
		if (el.value !== "")
			body[name] = el.value === "true";
		return;
	}
	if (type === "boolean") {
		body[name] = el.checked;
		return;
	}
	/* A field the form opened HOLDING a value, now emptied, is a
	 * request to clear it -- the opposite of an untouched empty field,
	 * which is omitted so that it keeps (#592). Without this an edit
	 * form could never clear anything: the recipe source's catalogue
	 * key is "" to remove, and the hand-built form sent it on every
	 * save to make that possible.
	 *
	 * NOT for a number, which has no empty value to send: "" for an
	 * integer reaches the daemon's json_as_number() as 0, so an emptied
	 * lease would be stored as a lease of 0 seconds. An emptied number
	 * is omitted, and keeps. */
	/* An empty NULLABLE field is `null` when the key must be sent or
	 * when it held a value the operator removed (#592) -- the migrate
	 * forms' "default placement", a volume handed back to root -- and
	 * omitted otherwise, like any untouched field. For a number, null
	 * is the empty value "" could never be. */
	if (el.dataset.nullable === "1" && fieldIsEmpty(el)) {
		if (el.dataset.required === "1" || el.dataset.initial === "1")
			body[name] = null;
		return;
	}
	if (el.dataset.initial === "1" && fieldIsEmpty(el) &&
	    type !== "integer" && type !== "number") {
		body[name] = type === "array" ? [] : type === "object" ? {} : "";
		return;
	}
	if (el.multiple) {
		const picked = Array.from(el.selectedOptions).map((o) => o.value);

		if (picked.length > 0 || el.dataset.required === "1")
			body[name] = picked;
		return;
	}
	if (type === "object" && el.dataset.fitems === "string") {
		if (el.value.trim() === "") {
			if (el.required)
				throw new Error(fieldLabel(name) + " is required");
			return;
		}
		body[name] = parseStringMap(fieldLabel(name), el.value);
		return;
	}
	/*
	 * A free-form object -- `additionalProperties`, so the contract
	 * names no fields to render -- is typed as JSON and parsed here. A
	 * schedule's `params` is one. `secrets` on applyDeployment was the
	 * first, until apigen read its values' type and it became the map
	 * of strings above (#592).
	 *
	 * It THROWS rather than reporting, because the one submit listener
	 * already calls this inside its own try/catch and shows the message
	 * on the status line without closing the modal: the typed text
	 * survives, which is the whole point when the text is the thing
	 * that was mistyped.
	 *
	 * Trimmed before the emptiness test below, because a textarea the
	 * operator tabbed through holds a newline rather than "".
	 */
	if (type === "object") {
		const text = el.value.trim();
		let parsed;

		if (text === "") {
			if (!el.required)
				return;
			throw new Error(fieldLabel(name) + " is required");
		}
		try {
			parsed = JSON.parse(text);
		} catch (e) {
			throw new Error(fieldLabel(name) + " must be valid JSON: " + e.message);
		}
		if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed))
			throw new Error(fieldLabel(name) + " must be a JSON object, not a bare value");
		body[name] = parsed;
		return;
	}
	/* `dataset.required`, not the attribute: a required array has no
	 * attribute (it may be empty) and must still be sent. And a line of
	 * text is read trimmed -- a space before or after a hostname or an
	 * address is never what anyone meant, and every hand-built form
	 * trimmed it; a document (a textarea) and a password are sent as
	 * typed. */
	if (textOf(el) === "" && el.dataset.required !== "1")
		return;
	if (type === "integer" || type === "number") {
		/* A size is typed in its unit and sent in bytes, rounded to a
		 * whole byte: 1.5 GiB is a size, 1.5 bytes is not. */
		body[name] = el._cixUnit !== undefined
			? Math.round(Number(el.value) * Number(el._cixUnit.value))
			: Number(el.value);
		return;
	}
	if (type === "array") {
		/* One item per LINE for `x-cix-ui: lines` -- an argv, where a
		 * comma list could never carry `-o a,b` (#592) -- and a comma
		 * list otherwise. */
		const items = el.value
			.split(el.dataset.ui === "lines" ? "\n" : ",")
			.map((s) => s.trim())
			.filter((s) => s.length > 0);
		const itemType = el.dataset.fitems;

		/* The item type decides, exactly as the field's own type decides
		 * a scalar -- a numeric list sent as strings is read by the
		 * daemon's json_as_number() as a list of zeroes, which is silent
		 * and wrong rather than refused. */
		body[name] = itemType === "integer" || itemType === "number"
			? items.map((s) => Number(s))
			: items;
		return;
	}
	body[name] = textOf(el);
}

/* A control's text: a single-line text input trimmed, anything else as
 * it stands. */
function textOf(el) {
	return el.type === "text" ? el.value.trim() : el.value;
}

function fieldIsEmpty(el) {
	if (el.multiple)
		return el.selectedOptions.length === 0;
	return el.value.trim() === "";
}

/*
 * The operation's path arguments: the ones the call site supplied, with
 * every one it did not supply read from the field the form rendered for
 * it (#592). In the contract's order, which is the route function's.
 */
function generatedFormArgs(form) {
	const args = JSON.parse(form.dataset.args || "[]");

	for (const el of form.querySelectorAll("[data-arg]"))
		args[Number(el.dataset.arg)] = el.value.trim();
	return args;
}

/*
 * The default `after`: whatever keeps the view the operator is looking
 * at honest.
 *
 * Every screen already declares its own refreshers in VIEW_REFRESHERS,
 * and both the poll loop and the tab bar run them that way -- so a
 * generated form needs no per-form refresh wiring at all. Each of the
 * 36 hand-written forms carried its own copy of that call, which is one
 * more thing that could be forgotten on the 37th.
 */
async function refreshVisibleView() {
	const view = document.querySelector(".view:not([hidden])");

	if (view !== null)
		await runRefreshers(refreshersForView(view.id));
}

/*
 * One value into its control, whatever control the field got.
 *
 * The inverse of generatedFormBody()'s own per-type reading, and it has
 * to be, or a form opened on a resource and submitted unchanged would
 * send something different from what it was given -- an array shown as
 * "a,b" and read back by splitting on commas, an object shown as JSON
 * and read back by parsing it.
 */
function setFieldValue(el, f, v) {
	if (v === undefined || v === null)
		return;
	if (f.ui === "tristate") {
		el.value = v === true ? "true" : "false";
		return;
	}
	if (f.type === "boolean") {
		el.checked = v === true;
		return;
	}
	/* Remembered, so that emptying it later reads as "clear" rather
	 * than as "leave alone" (generatedFormBody()). */
	if (!(Array.isArray(v) && v.length === 0) && v !== "" &&
	    !(typeof v === "object" && !Array.isArray(v) && Object.keys(v).length === 0))
		el.dataset.initial = "1";
	if (el.multiple) {
		const want = Array.isArray(v) ? v.map(String) : [String(v)];

		for (const o of el.options)
			o.selected = want.indexOf(o.value) !== -1;
		return;
	}
	if (el._cixUnit !== undefined && typeof v === "number") {
		const u = BYTE_UNITS.find(([n]) => v >= n && v % n === 0) || [1];

		el._cixUnit.value = String(u[0]);
		el.value = String(v / u[0]);
		return;
	}
	if (f.type === "array") {
		el.value = Array.isArray(v) ? v.join(f.ui === "lines" ? "\n" : ", ") : String(v);
		return;
	}
	if (isStringMap(f) && typeof v === "object") {
		el.value = stringMapText(v);
		return;
	}
	if (f.type === "object") {
		/* Indented, because the operator is about to read and edit it
		 * -- JSON.stringify's default one-line form is not a thing
		 * anyone edits in a textarea. */
		el.value = typeof v === "string" ? v : JSON.stringify(v, null, 2);
		return;
	}
	el.value = String(v);
}

/*
 * Open the generated form for one operation.
 *
 * opts.title    the modal's heading                (authored)
 * opts.submit   the words on the button            (authored)
 * opts.args     the operation's path parameters, in contract order;
 *               one not given is asked for, as a field of its own
 * opts.before   (body) => bool: a question before sending (authored)
 * opts.after    what to refresh once it succeeds   (authored)
 * opts.failed   what to say if it does not         (authored)
 * opts.values   starting values, by field name -- a draft to edit
 * opts.fixed    values that IDENTIFY the resource, so not editable
 * opts.choices  { field: [{ value, label }] } -- what really exists to
 *               pick from, read from the box by the call site
 * opts.secrets  { field: true } -- a secret the resource already holds,
 *               so the form can keep, replace or remove it
 * opts.sections [{ title, fields: [name, ...] }] -- the layout of a long
 *               form (authored); `choices` reach a list's rows by a
 *               dotted key, "networks.name"
 * opts.saved    what a form on a page says once it has saved (authored;
 *               "Saved" otherwise -- a modal says it by closing)
 * opts.changedOnly  send only the fields the operator changed: for a
 *               partial update whose daemon treats a value echoed back
 *               as a change (authored, per operation)
 * opts.clear    rebuild the form empty after a successful submit -- an
 *               action on a page (stage an update, add a partition),
 *               whose typed values are spent once it has run
 *
 * `values` and `fixed` are two different facts and not one with a flag.
 * An upsert keyed by a body field -- addImageRecipe, addDeployment --
 * is the SAME operation for a create and for an edit, and the only
 * difference is that on an edit the key names a resource that already
 * exists: typing over it would not rename anything, it would quietly
 * address a different one. So `fixed` renders read-only and is still
 * SENT, because the operation needs it. That is a separate thing from
 * the contract's own `readOnly`, which means the daemon reports this
 * field and never accepts it -- those fields are not rendered at all.
 */
function openForm(opId, opts) {
	const options = opts || {};

	if (CIX_API[opId + "_SHAPE"] === undefined) {
		showStatus("No such operation: " + opId, true);
		return;
	}
	/*
	 * The modal opens BEFORE the fields are built, and the order is
	 * load-bearing: openModal() begins by calling closeModal(), which
	 * empties this form precisely so nothing typed survives a close.
	 * Building first and opening second would therefore have shown an
	 * empty form every time.
	 */
	openModal("generated-form", options.title || fieldLabel(opId));
	bindForm(document.getElementById("generated-form"), opId, options);
}

/*
 * A FORM ON A PAGE, kept in step with the box (#592).
 *
 * A settings form sits on its page for as long as the page is open, and
 * the page re-reads what it shows on every poll. Every hand-built one
 * carried its own flag for the same rule -- `siteConfigDirty`,
 * `daemonConfigDirty`, and the rest: refill from the fresh read unless
 * the operator has started typing, because a poll that rebuilds a form
 * under someone's cursor throws away what they typed. That rule lives
 * here now, once.
 *
 * Call it from the page's refresh with the values just read. It builds
 * the form the first time, rebuilds it when the operation, its path
 * arguments or the values changed -- unless the operator has typed into
 * it since -- and otherwise does nothing, so an unchanged poll costs no
 * DOM at all. A successful save clears the mark (submitForm()).
 */
function syncForm(form, opId, opts) {
	const options = opts || {};
	const c = form._cix;
	const sameTarget = c !== undefined && c.opId === opId &&
		JSON.stringify(c.args) === JSON.stringify(options.args || []);

	if (c !== undefined && c.sig === formSignature(opId, options))
		return;
	/* The operator's: typed into, or simply holding the focus -- a
	 * select dropped open has not changed yet, and rebuilding it would
	 * close it under the pointer. */
	if (sameTarget && (form.dataset.dirty === "1" ||
	    (typeof document.activeElement === "object" && document.activeElement !== null &&
	     typeof form.contains === "function" && form.contains(document.activeElement))))
		return;
	bindForm(form, opId, options);
}

/*
 * What a form shows, as one string, for syncForm()'s "has anything
 * changed" -- built from the operation's own WRITABLE fields only. A
 * GET response carries more than the form shows (an effective value, a
 * status, a derived flag), and some of it changes on every read; signing
 * the whole response would rebuild the form on every poll, which is the
 * thing syncForm() exists to stop.
 */
function formSignature(opId, options) {
	const shape = CIX_API[opId + "_SHAPE"];
	const fields = shape && shape.request ? CIX_API.FIELDS[shape.request] || [] : [];
	const values = options.values || {};
	const shown = {};

	for (const f of fields)
		if (!f.readOnly && Object.prototype.hasOwnProperty.call(values, f.name))
			shown[f.name] = values[f.name];
	return JSON.stringify([opId, options.args || [], shown, options.fixed || {},
	                       options.choices || {}]);
}

/*
 * Build an operation's form into a <form> element -- the modal's or
 * one on a page -- and hold what its submit needs ON THE ELEMENT (#592).
 *
 * Those three used to be module globals, which was right while there
 * was one generated form and wrong the moment a page holds several: the
 * globals would be the last form built, not the one submitted.
 */
function bindForm(form, opId, opts) {
	const shape = CIX_API[opId + "_SHAPE"];
	const options = opts || {};
	const fields = shape && shape.request ? CIX_API.FIELDS[shape.request] || [] : [];
	const argFields = shape && shape.args ? CIX_API.FIELDS[shape.args] || [] : [];
	const given = options.args || [];
	const choices = options.choices || {};
	const secrets = options.secrets || {};
	const button = document.createElement("button");
	const allowed = sessionMay(opId);

	if (shape === undefined) {
		showStatus("No such operation: " + opId, true);
		return;
	}
	form.textContent = "";
	/* The layout's hook: every generated form is one column, wherever
	 * it is mounted. */
	if ((" " + (form.className || "") + " ").indexOf(" generated-form ") < 0)
		form.className = ((form.className || "") + " generated-form").trim();
	form.dataset.opId = opId;
	form.dataset.args = JSON.stringify(given);
	form.dataset.dirty = "";
	form._cix = {
		opId: opId,
		args: given,
		before: options.before || null,
		after: options.after || refreshVisibleView,
		failed: options.failed || ("Failed to " + (options.submit || "submit")),
		saved: options.saved,
		changedOnly: options.changedOnly === true,
		/* Kept so a form can be rebuilt as it was bound: empty again
		 * after an action (`clear`), whose fields mean nothing once
		 * the action has run. */
		opts: options,
		sig: formSignature(opId, options),
	};
	/* Typing marks the form as the operator's, so a poll leaves it be
	 * (syncForm()). Bound once per element: a form is rebuilt in place,
	 * and a second listener per rebuild would leak. */
	if (!form._cixTyping) {
		form._cixTyping = true;
		form.addEventListener("input", () => { form.dataset.dirty = "1"; });
		form.addEventListener("change", () => { form.dataset.dirty = "1"; });
	}

	/*
	 * The path parameters the call site did not supply, FIRST, because
	 * they name the thing the rest of the form describes -- the sysctl
	 * key before its value, the module before its options (#592). One
	 * the call site did supply is not shown: an edit opened on a
	 * resource already says which in its title, and every edit form
	 * before this one worked that way.
	 */
	argFields.forEach((f, i) => {
		let control;

		if (given[i] !== undefined && given[i] !== null)
			return;
		control = fieldControl(f, choices[f.name]);
		delete control.dataset.field;
		control.dataset.arg = String(i);
		form.appendChild(fieldRow(f, control));
	});

	/*
	 * SECTIONS, where the call site authors them (#592): which fields
	 * belong together, and in what order, is layout -- ADR-0338 leaves
	 * that to a person, as it leaves a table's columns. A field no
	 * section names is still drawn, in a trailing "Other" section, so a
	 * property added to the contract appears rather than waiting for
	 * someone to place it. Always-open fieldsets, never collapsed: an
	 * invalid control inside a closed <details> fails the submit with
	 * nothing on screen to say which.
	 */
	const ctx = {
		values: options.values || {},
		fixed: options.fixed || {},
		choices: choices,
		secrets: secrets,
		optional: false,
	};

	if (Array.isArray(options.sections)) {
		const placed = {};
		let rest;

		for (const sec of options.sections) {
			const subset = sec.fields
				.map((n) => fields.find((f) => f.name === n))
				.filter((f) => f !== undefined && !f.readOnly);

			for (const f of subset)
				placed[f.name] = true;
			if (subset.length > 0)
				form.appendChild(formSection(sec.title, subset, ctx));
		}
		rest = fields.filter((f) => !placed[f.name] && !f.readOnly);
		if (rest.length > 0)
			form.appendChild(formSection("Other", rest, ctx));
	} else {
		buildFields(form, fields, ctx);
	}
	button.type = "submit";
	button.textContent = options.submit || "Save";
	if (shape.destructive)
		button.className = "button-danger";
	/* web-ux-guidelines: a submit sets disabled and its reason from
	 * sessionMay() directly. It also carries `data-op`, because a form
	 * on a page is built once and outlives a login: the session sweep
	 * (applySessionEligibility()) re-gates every `[data-op]` control,
	 * and without the attribute a settings form would stay dead after
	 * the operator logged in on the page. */
	button.dataset.op = opId;
	button.disabled = !allowed;
	if (!allowed)
		button.title = sessionRefusal(opId);
	form.appendChild(button);
}

/*
 * Fields into a container, each as the contract describes it -- the
 * one builder for a form's top level, a section, a group and a row
 * (#592). `ctx` carries what the call site knows: starting values,
 * fixed keys, choices, stored secrets, and whether this level is
 * inside an optional group (whose inputs are then never browser-
 * `required`; collectGroup() asks for them only once the group is
 * used).
 */
function buildFields(container, fields, ctx) {
	for (const f of fields) {
		let control;
		let label;

		/* A field the daemon only ever reports is not a field anyone
		 * fills in. */
		if (f.readOnly)
			continue;
		if (f.of !== undefined && CIX_API.FIELDS[f.of] !== undefined) {
			container.appendChild(f.type === "array" ? listRow(f, ctx) : groupRow(f, ctx));
			continue;
		}
		control = fieldControl(f, ctx.choices[f.name]);
		/* Both marks, not only the attribute: `dataset.required` is
		 * what makes the collector send an empty field, and an empty
		 * field sent from an untouched optional group makes that group
		 * look filled in. collectGroup() asks for its required fields
		 * itself, once the group is in use. */
		if (ctx.optional) {
			control.required = false;
			delete control.dataset.required;
		}
		/* `readOnly` is right for every `fixed` field there is or is
		 * likely to be -- a key is a name, so a text input. It is inert
		 * on a `<select>`, so a fixed enum would show as editable; that
		 * is a real gap and not a current one, and the fix when it
		 * arrives is `disabled` plus keeping the value in the body,
		 * which generatedFormBody() already would. */
		if (Object.prototype.hasOwnProperty.call(ctx.fixed, f.name)) {
			setFieldValue(control, f, ctx.fixed[f.name]);
			control.readOnly = true;
		} else {
			setFieldValue(control, f, ctx.values[f.name]);
		}
		/* What the control reads as before anyone touches it, so a
		 * changed-only form can leave out what nobody changed. */
		control._cixStart = startValue(control);
		if (control._cixUnit !== undefined) {
			const pair = document.createElement("span");

			pair.className = "field-size";
			pair.appendChild(control);
			pair.appendChild(control._cixUnit);
			label = fieldRow(f, pair, null);
		} else {
			label = fieldRow(f, control, f.ui === "textarea" ? fileLoader(control) : null);
		}
		container.appendChild(label);
		/*
		 * A SECRET THE RESOURCE ALREADY HOLDS (#592) can be kept,
		 * replaced or removed, and an empty field can only mean one of
		 * those: keep, because the operator was never shown it. So the
		 * other two need a control each -- typing replaces, and this box
		 * removes. Only where the call site says the secret is set
		 * (`secrets`), since a box to clear nothing is a question with
		 * no meaning.
		 */
		if (f.format === "password" && ctx.secrets[f.name]) {
			const clear = document.createElement("label");
			const box = document.createElement("input");

			control.placeholder = "Set — leave empty to keep it";
			clear.className = "checkbox";
			box.type = "checkbox";
			box.dataset.clearFor = f.name;
			clear.appendChild(box);
			clear.appendChild(document.createTextNode("Remove the stored " +
			                                          fieldLabel(f).toLowerCase()));
			container.appendChild(clear);
		}
	}
}

/*
 * A control's value as the body would carry it, serialized, or "" when
 * it would carry nothing -- read once at build, compared at submit.
 * A control whose reading throws (unparseable JSON a resource sent) has
 * no start, so any value it holds at submit counts as changed.
 */
function startValue(control) {
	const probe = {};

	try {
		readField(control, probe, {});
	} catch (e) {
		return undefined;
	}
	return JSON.stringify(probe[control.dataset.field]);
}

/* The choices for one level down: `"networks.name"` is what the rows
 * of `networks` offer for their `name`. */
function subChoices(choices, prefix) {
	const out = {};

	for (const k of Object.keys(choices))
		if (k.indexOf(prefix + ".") === 0)
			out[k.slice(prefix.length + 1)] = choices[k];
	return out;
}

/* A section of a long form: a legend and the fields it holds. */
function formSection(title, fields, ctx) {
	const fs = document.createElement("fieldset");
	const legend = document.createElement("legend");

	fs.className = "form-section";
	legend.textContent = title;
	fs.appendChild(legend);
	buildFields(fs, fields, ctx);
	return fs;
}

/* A group's or a list's own heading: the same head row and hint a
 * field has, on a fieldset's legend instead of a label. */
function fieldGroupShell(f) {
	const fs = document.createElement("fieldset");
	const legend = document.createElement("legend");

	fs.className = "field-group";
	fs.dataset.label = f.title !== undefined ? f.title : f.name;
	if (f.required)
		fs.dataset.required = "1";
	legend.appendChild(fieldHead(f));
	fs.appendChild(legend);
	if (f.description !== undefined)
		fs.appendChild(fieldHintEl(f));
	return fs;
}

/*
 * AN OBJECT THE CONTRACT NAMES (#592) -- `dns_server`, a service's
 * `ready` probe -- drawn as its schema's own fields, grouped, rather
 * than as a JSON box. Optional unless the contract says otherwise, and
 * an optional group's inputs are never browser-required (see
 * collectGroup()).
 */
function groupRow(f, ctx) {
	const fs = fieldGroupShell(f);

	fs.dataset.group = f.name;
	fs.dataset.of = f.of;
	buildFields(fs, CIX_API.FIELDS[f.of], {
		values: ctx.values[f.name] || {},
		fixed: {},
		choices: subChoices(ctx.choices, f.name),
		secrets: {},
		optional: ctx.optional || !f.required,
	});
	return fs;
}

/*
 * AN ARRAY OF OBJECTS THE CONTRACT NAMES (#592) -- a container's
 * services, networks, files, volumes -- drawn as rows, each its
 * schema's own fields, with Add and Remove. A required list opens with
 * one row, since it cannot be sent with none.
 *
 * A row's inputs are browser-required as their schema says: a row
 * exists only because the operator added it, so what it needs is
 * needed.
 */
function listRow(f, ctx) {
	const fs = fieldGroupShell(f);
	const rows = document.createElement("div");
	const add = document.createElement("button");
	const start = ctx.values[f.name];
	const sub = subChoices(ctx.choices, f.name);
	const itemFields = CIX_API.FIELDS[f.of];
	const addRow = (v) => {
		const row = document.createElement("div");
		const rm = document.createElement("button");

		row.className = "field-item";
		row.dataset.item = "1";
		/* A bare string in a `oneOf` list is shorthand for the row's
		 * first field: `"lan"` is `{name: "lan"}`. */
		if (typeof v === "string")
			v = { [itemFields[0].name]: v };
		buildFields(row, itemFields, {
			values: v || {}, fixed: {}, choices: sub, secrets: {}, optional: false,
		});
		rm.type = "button";
		/* Neutral, not danger: it takes a row out of a form that has
		 * not been sent, so nothing anywhere is destroyed. */
		rm.className = "button-small";
		rm.textContent = "Remove";
		rm.addEventListener("click", () => rows.removeChild(row));
		row.appendChild(rm);
		rows.appendChild(row);
	};

	fs.dataset.list = f.name;
	rows.className = "field-rows";
	rows.dataset.rows = "1";
	fs.appendChild(rows);
	add.type = "button";
	add.className = "button-small";
	add.textContent = "Add";
	add.addEventListener("click", () => addRow());
	fs.appendChild(add);
	if (Array.isArray(start) && start.length > 0)
		start.forEach((v) => addRow(v));
	else if (f.required && !ctx.optional)
		addRow();
	return fs;
}

/*
 * A DOCUMENT FIELD CAN BE READ FROM A FILE (#592). A recipe is a file
 * on someone's disk far more often than it is typed, and both
 * hand-built recipe forms offered this. Derived from the field being a
 * document -- `x-cix-ui: textarea` -- so every such field has it, and
 * it FILLS the textarea rather than replacing it: the operator sees
 * what will be sent, and can still edit it.
 */
function fileLoader(textarea) {
	const file = document.createElement("input");

	file.type = "file";
	file.className = "field-file";
	file.addEventListener("change", async () => {
		if (file.files.length > 0)
			textarea.value = await file.files[0].text();
	});
	return file;
}

/*
 * One field as the Generated board draws it: a head row, the control,
 * one sentence of hint -- all inside one label (#592 made it its own
 * function, because a path parameter is drawn exactly like a body
 * field and is not a body field). `extra`, when given, sits directly
 * under the control: the file picker that fills a document field.
 */
function fieldRow(f, control, extra) {
	const label = document.createElement("label");

	label.appendChild(fieldHead(f));
	/*
	 * A boolean uses the dashboard's own checkbox layout -- name beside
	 * a real-sized box, not above a full-width one. Without the class,
	 * the global `form input` rule (width: 100%, height: 2.25rem, which
	 * exists so text fields line up) makes a checkbox a large grey
	 * square. Rendering pkgInstall is what showed it; `form
	 * label.checkbox input[type="checkbox"]` already existed for the
	 * hand-written forms. A `tristate` boolean is a select, and is
	 * laid out like one.
	 *
	 * No `.wide` here any more: the generated form is one column, so
	 * every field already spans it.
	 */
	if (f.type === "boolean" && f.ui !== "tristate")
		label.className = "checkbox";
	label.appendChild(control);
	if (extra !== undefined && extra !== null)
		label.appendChild(extra);
	/*
	 * The hint goes INSIDE the label, not beside it.
	 *
	 * A dashboard form is a grid -- `repeat(auto-fit, minmax(15rem,
	 * 1fr))` -- so a hint appended to the form is its own grid item and
	 * lands in the NEXT COLUMN, reading as a peer of the field rather
	 * than as its explanation. Rendering the real modal is what showed
	 * it: the syslog field sat in column one with its own description
	 * beside it in column two.
	 *
	 * The hand-written forms had the same shape, so this is not a
	 * regression -- but they carried 185 hints between them while the
	 * contract has a description for 583 fields, so what was an oddity
	 * on a few forms would have become the norm on every one. Inside
	 * the label, `form label`'s own flex column stacks name, control
	 * and hint as one cell.
	 */
	if (f.description !== undefined)
		label.appendChild(fieldHintEl(f));
	return label;
}

/*
 * ONE SENTENCE, with the whole thing on hover.
 *
 * The contract's descriptions are reference documentation -- 331
 * characters on average and up to 2,064 -- because that is the right
 * length for the document they were written in. Rendered verbatim, a
 * four-field form becomes a wall of prose taller than the modal:
 * pkgInstall's four fields produced four paragraphs and pushed its own
 * submit button off the bottom. fieldHint() takes the first sentence,
 * and `title` carries the full text, so nothing is truncated in api.js
 * and the contract stays the source.
 */
function fieldHintEl(f) {
	const hint = document.createElement("p");

	hint.className = "hint";
	hint.textContent = fieldHint(f);
	hint.title = f.description;
	return hint;
}

/*
 * The label ROW, which the Generated board specifies as three things on
 * one line: the operator's word, whether the field is required, and the
 * constraint in monospace on the right.
 *
 * All three are facts the schema already states and that the dashboard
 * used to keep to itself -- a required field looked exactly like an
 * optional one, and the 174 constraints were enforced invisibly by the
 * input until it refused to submit.
 */
function fieldHead(f) {
	const head = document.createElement("span");
	const name = document.createElement("span");
	const req = document.createElement("span");
	const rule = constraintText(f);

	head.className = "field-head";
	name.className = "field-name";
	name.textContent = fieldLabel(f);
	head.appendChild(name);
	/* Both words, as the board draws them. Marking only the exception
	 * was the tidier instinct and it is wrong here: an unmarked field
	 * reads as "nobody said", and a form an operator is meeting for the
	 * first time should not make them infer which of the two it is. */
	req.className = f.required ? "field-req" : "field-opt";
	req.textContent = f.required ? "required" : "optional";
	head.appendChild(req);
	if (rule !== "") {
		const chip = document.createElement("span");

		chip.className = "field-rule";
		chip.textContent = rule;
		head.appendChild(chip);
	}
	return head;
}

/*
 * ---------- the primitives, and the two renderers over them ----------
 *
 * `fieldBlock` and `simpleTableRows` moved here from app.js unchanged
 * (83 and 15 callers, all unaffected -- both are globals). They are the
 * design system's PRIMITIVES layer: pure DOM builders with no screen
 * knowledge, which is both why they belong beside the renderers that
 * compose them and why they can be tested at all.
 */
function fieldBlock(label, value) {
	const row = document.createElement("tr");
	const labelCell = document.createElement("th");
	const valueCell = document.createElement("td");

	labelCell.className = "field-label";
	labelCell.scope = "row";
	labelCell.textContent = label;
	row.appendChild(labelCell);
	valueCell.textContent = value;
	row.appendChild(valueCell);
	return row;
}

function simpleTableRows(bodyEl, columns, colCount, emptyText, emptyCls) {
	bodyEl.textContent = "";
	if (columns.length === 0) {
		const row = document.createElement("tr");
		const cell = document.createElement("td");

		cell.colSpan = colCount;
		cell.className = emptyCls ? "empty " + emptyCls : "empty";
		cell.textContent = emptyText;
		row.appendChild(cell);
		bodyEl.appendChild(row);
		return;
	}
	for (const cols of columns) {
		const row = document.createElement("tr");

		for (const col of cols) {
			const cell = document.createElement("td");

			cell.textContent = col;
			row.appendChild(cell);
		}
		bodyEl.appendChild(row);
	}
}

/*
 * ONE VALUE, AS TEXT, DECIDED BY ITS FIELD.
 *
 * This is the half of the incoherence that is measurable rather than
 * aesthetic. Counted in app.js on 2026-10-10, before this existed:
 *
 *   a boolean reads "yes"/"no" 16 times, "enabled"/"disabled" 4 times
 *   and "true"/"false" once;
 *
 *   an absent value reads "-" 67 times, "none" 41, "unknown" 12,
 *   "unset" 4 and "—" 3.
 *
 * So the same fact reads five different ways depending on which page an
 * operator is looking at, and nothing anywhere decided that. The field
 * decides it now.
 *
 * The one subtlety is worth stating because the hand-written code had
 * it right and a naive version would get it wrong: an ABSENT boolean is
 * not unknown if its schema declares a default. `s.enabled === false ?
 * "no" : "yes"` is in app.js today for a field that defaults to true,
 * and it is correct -- so the contract's own `default` (emitted as
 * `fallback`) is consulted before anything is called absent.
 */
const FIELD_ABSENT = "—";

/*
 * AN INSTANT, IN THE READER'S OWN LOCAL TIME.
 *
 * `format: unix-seconds` is what makes a bare integer a moment rather
 * than a count, and this is the one place that turns it into words.
 * There were twenty copies of `new Date(x * 1000).toLocale*String()`
 * before it, each free to disagree about whether to show the date --
 * and two of them did, printing a bare time for a block that may lift
 * tomorrow.
 *
 * ZERO IS ABSENT. No instant this daemon reports is legitimately
 * 1970-01-01, and two properties say so outright: `blocked_until` is
 * *"0 if it is not currently blocked"*. A hand-written cell guarded
 * that with its own `&&`, which a renderer reading the format cannot
 * do, so the rule belongs here rather than in each caller.
 *
 * The format is COINED and not borrowed, which is worth recording:
 * OpenAPI has no standard format for an epoch integer, and the
 * pattern everyone recommends is `format: int64` plus a description
 * saying "Unix seconds" -- which is exactly the shape a renderer
 * cannot read. So the spelling is the phrase this contract's own prose
 * already used eleven times.
 */
function formatInstant(seconds) {
	if (seconds === undefined || seconds === null || seconds === 0)
		return FIELD_ABSENT;
	return new Date(seconds * 1000).toLocaleString();
}

function fieldText(f, value) {
	const type = f !== undefined ? f.type : "string";
	let v = value;

	if ((v === undefined || v === null) && f !== undefined && f.fallback !== undefined)
		v = f.fallback;
	if (v === undefined || v === null)
		return FIELD_ABSENT;
	if (f !== undefined && f.format === "unix-seconds")
		return formatInstant(v);
	if (type === "boolean")
		return v ? "yes" : "no";
	if (type === "array") {
		if (!Array.isArray(v) || v.length === 0)
			return FIELD_ABSENT;
		/*
		 * An array of OBJECTS is counted, never joined -- joining one
		 * prints "[object Object], [object Object]". Decided on the
		 * values rather than on `items`, because apigen records an
		 * item type only for an inline scalar: an array of `$ref`
		 * objects (a network's `interfaces`) carries no `items` at all,
		 * so the schema cannot tell this branch which case it is in.
		 */
		if (v.some((e) => e !== null && typeof e === "object"))
			return String(v.length);
		return v.join(", ");
	}
	if (type === "object")
		return FIELD_ABSENT;
	if (v === "")
		return FIELD_ABSENT;
	return String(v);
}

/* The field descriptor for one name, or undefined. */
function schemaField(schema, name) {
	const fields = CIX_API.FIELDS[schema];

	if (fields === undefined)
		return undefined;
	return fields.find((f) => f.name === name);
}

/* A column's heading: authored if it says so, else the field's own
 * `title` from the contract, else the field name de-cased. So a header
 * and its column are one fact in one place -- which is the whole
 * reason `renderTable` owns the `<thead>` rather than leaving it in
 * `index.html` beside a column list in JavaScript. */
function columnLabel(schema, col) {
	if (typeof col === "string")
		return fieldLabel(schemaField(schema, col) || col);
	if (col.label !== undefined)
		return col.label;
	return fieldLabel(schemaField(schema, col.field) || col.field);
}

/*
 * ONE CELL. Text is always derived; the three other forms are authored
 * because none of them is in the schema.
 *
 * A LINK is a route this dashboard chose (`#images/<name>`), not a
 * fact about the field. A BADGE needs a domain's own state mapped to
 * one of the four semantic kinds, which `statusBadge`'s own comment
 * says is the caller's knowledge -- "running" means ok for a container
 * and nothing at all for a disk. ACTIONS are the operations this page
 * offers on a row, which is judgement of exactly the kind ADR-0338
 * reserves for a person.
 *
 * What is NOT authored, in any of the four: the text. It comes from
 * `fieldText()` through the field's own type, so a boolean reads "yes"
 * here exactly as it does on a detail page, and an absent value is the
 * same dash everywhere.
 */
function tableCell(schema, row, col) {
	const cell = document.createElement("td");

	if (typeof col === "object" && col.cls !== undefined)
		cell.className = col.cls;
	/*
	 * `title` -- the hover, for a cell whose full value does not fit a
	 * dense row. Five hand-written cells had one and three were the
	 * identical `stateCell.title = pkg.error` (#101's rule: the state
	 * and its kind sit in the cell, the message is the hover, so the
	 * table stays readable). An empty string sets no attribute, so a
	 * row with nothing to add gets no empty tooltip.
	 */
	if (typeof col === "object" && col.title !== undefined) {
		const t = col.title(row);

		if (t)
			cell.title = t;
	}
	if (typeof col === "object" && col.actions !== undefined) {
		for (const el of col.actions(row) || [])
			cell.appendChild(el);
		return cell;
	}
	/*
	 * `fill` -- a cell whose content is fetched after its row exists.
	 * A volume's measured size is a tree walk, asked for per row
	 * rather than carried by the list, so the cell is handed over
	 * empty and the caller writes into it when the answer comes.
	 * Added on 2026-10-17 for the storage page's volumes. A
	 * container's volumes table fills its backups cell the same way
	 * and still stays hand-written, for a different reason: it is
	 * re-read on every two-second sweep so that cell stays live, and
	 * this renderer's repaint guard exists to stop exactly that.
	 */
	if (typeof col === "object" && col.fill !== undefined) {
		col.fill(row, cell);
		return cell;
	}
	/*
	 * WHERE THE STRING COMES FROM is one decision, and what wraps it
	 * is another -- so `text` no longer returns early. A derived
	 * string can wear a badge or be a link, which it could not before:
	 * two tables marked a row with a bare `<strong>` ("current", "(rolling
	 * candidate)") where the vocabulary has a badge, and neither mark
	 * is a field, so the only way to render one correctly was to build
	 * the cell by hand.
	 */
	const derived = typeof col === "object" && col.text !== undefined;
	const name = derived ? null : (typeof col === "string" ? col : col.field);
	const text = derived ? col.text(row)
	                     : fieldText(schemaField(schema, name), row[name]);

	if (typeof col === "object" && col.link !== undefined) {
		const href = col.link(row);

		/* A link only where there is somewhere to go: a granted device
		 * links to its name mapping when it has one, and is plain text
		 * when it does not, rather than a link to nowhere. */
		if (href)
			cell.appendChild(treeLink(href, text, ""));
		else
			cell.textContent = text;
		return cell;
	}
	if (typeof col === "object" && col.badge !== undefined) {
		const span = document.createElement("span");

		/* No text, no badge: an empty badge is a coloured smudge
		 * asserting something about a row that has nothing to say.
		 * This is how a "current version" column marks one row and
		 * leaves the rest alone. */
		if (text === "")
			return cell;
		{
			const kind = col.badge(derived ? text : row[name], row);

			/* A null kind is plain text: a badge that marks only the
			 * one row that is a problem -- software with no recipe --
			 * and leaves "yes" as the ordinary word it is. */
			if (kind === null) {
				cell.textContent = text;
				return cell;
			}
			span.className = statusBadge(kind);
		}
		span.textContent = text;
		cell.appendChild(span);
		return cell;
	}
	cell.textContent = text;
	return cell;
}

/*
 * A LIST TABLE: its header, its rows, its four empty states and its
 * repaint guard, from the schema and an authored column list.
 *
 * This is story 3 of #592, and `renderTableRows` alone was not it.
 * That function derived cell TEXT and left every caller to build its
 * own header in markup, its own empty row, its own guard, and its own
 * link/badge/action cells -- which is why, measured on 2026-10-11, it
 * had **zero callers** after a release: only five of some thirty hand
 * written tables are pure text, so a renderer that could not express a
 * button fitted almost none of them. It was deleted on 2026-10-16,
 * still with no caller, once this function had thirty-five.
 *
 * `columns` is the authored part, and takes these forms:
 *
 *   "name"                                  text, header from the schema
 *   { field, label }                        text, authored header
 *   { field, link: (row) => "#..." }        text inside a tree link
 *   { field, badge: (value, row) => kind }  text inside a status badge
 *   { label, actions: (row) => [el, ...] }  authored controls, no field
 *   { label, text: (row) => "..." }         a cell that is not one field
 *   { label, fill: (row, cell) => {} }      a cell filled after it exists
 *
 * `text` COMPOSES with `link` and `badge`, because where a string
 * comes from and what wraps it are two separate decisions. `{ label,
 * text, badge }` is a status marker derived from more than one field
 * -- which is what "current" is for an image version, where current-
 * ness is `version === data.current_version` -- and a `text` returning
 * "" gets no badge at all rather than an empty coloured smudge.
 *
 * and any of them may carry `cls` -- a class the stylesheet already
 * defines, for a column whose content wants one (a sysctl key is
 * monospace because it is an identifier, not prose). It names an
 * existing class and never a rule: a screen that invents styling is
 * the defect the four-layer rule describes, and the class-orphan gate
 * would refuse a name nothing defines anyway.
 *
 * Any of them may also carry `title: (row) => "..."`, the hover for a
 * cell whose whole value will not fit a dense row.
 *
 * That last form is the narrow escape hatch and is meant to stay
 * narrow: it exists for a cell with NO single field behind it -- a
 * DHCP range is `range_start – range_end`, two fields joined, and the
 * join is judgement. It is not for re-wording one field, because that
 * is how three tables came to spell one boolean three ways. If a cell
 * names exactly one field, it takes its text from the field.
 *
 * `state` is `{ op, what, empty, key?, extra? }` -- the operation this
 * list is read by, its subject, and the sentence for "it answered and
 * there are none". The other three outcomes come from
 * `emptyStateText()`, and the guard keys on `op` so no caller invents
 * a cache key either.
 *
 * `key` and `extra` exist for the case where the same operation feeds
 * a table whose content depends on the route: an image's "containers
 * using this image" is filtered from `listContainers`, so two images
 * with identical lists must still redraw when you navigate between
 * them. `extra` goes into the compared signature, `key` names the
 * cache slot. Omit both and the op is the whole of each, which is
 * right for a table that shows one list once.
 *
 * `op: null` is a list that was never separately read -- a field of
 * an object the page already holds, like a network's `interfaces`.
 * It has ONE state, the authored sentence, and no loading or refused
 * one, because there is no read of its own to be pending or refused.
 * Such a table must name its `key`, since there is no op to key the
 * repaint guard on; test_web_tree refuses one that does not, and
 * refuses a call that states no `op` at all, so the choice between
 * the two is always written down.
 */
function renderTable(tableEl, schema, rows, columns, state) {
	const data = rows || [];
	const sig = listSignature(data, state.op, state.what, state.empty);
	let body = tableEl.tBodies[0];

	if (body === undefined || body === null) {
		body = document.createElement("tbody");
		tableEl.appendChild(body);
	}
	if (unchangedAndRendered(body, state.key || state.op,
	    state.extra === undefined ? sig : { extra: state.extra, sig: sig }))
		return;

	/* The header is rebuilt with the body so the two cannot disagree;
	 * an authored column list that grows a column grows its heading in
	 * the same statement. */
	{
		const head = tableEl.createTHead();
		const hrow = document.createElement("tr");

		head.textContent = "";
		for (const col of columns) {
			const th = document.createElement("th");

			th.textContent = columnLabel(schema, col);
			hrow.appendChild(th);
		}
		head.appendChild(hrow);
	}

	body.textContent = "";
	if (data.length === 0) {
		const st = listState(state.op, state.what, state.empty);

		/* Only a refusal takes a class: loading and empty are muted,
		 * which is what `td.empty` already is. */
		simpleTableRows(body, [], columns.length, st.text,
		    st.kind === "refused" ? "empty-refused" : null);
		return;
	}
	for (const row of data) {
		const tr = document.createElement("tr");

		for (const col of columns)
			tr.appendChild(tableCell(schema, row, col));
		body.appendChild(tr);
	}
}

/*
 * A detail page's key/value rows, in SCHEMA order.
 *
 * Schema order rather than an authored list, because a detail page's job
 * is to show everything known about one resource -- when a page wants a
 * subset it passes one, and when it does not, adding a field to the
 * contract makes it appear rather than being silently absent until
 * someone notices.
 *
 * A read-only field is shown (unlike a form, which omits it): "the
 * daemon reports this and you cannot set it" is exactly what a detail
 * page is for.
 *
 * `opts` is `{ only, omit }`, and `omit` is the one a page normally
 * wants. `only` is an allow-list, which is exactly the property the
 * paragraph above exists to avoid: a field added to the contract
 * later is silently absent. `omit` names what this page shows
 * ELSEWHERE -- the name that is already its heading, a list that has
 * its own table below -- and leaves every other field, including the
 * next one, appearing by default.
 *
 * The label is the FIELD's, so the contract's `title` is used. Until
 * this had a caller it passed `fieldLabel(f.name)`, a bare string, and
 * a title could never have reached a detail page.
 */
function renderDetailRows(bodyEl, schema, obj, opts) {
	const fields = CIX_API.FIELDS[schema] || [];
	const only = opts && Array.isArray(opts.only) ? opts.only : null;
	const omit = opts && Array.isArray(opts.omit) ? opts.omit : [];

	bodyEl.textContent = "";
	for (const f of fields) {
		if (only !== null && !only.includes(f.name))
			continue;
		if (omit.includes(f.name))
			continue;
		bodyEl.appendChild(fieldBlock(fieldLabel(f), fieldText(f, obj[f.name])));
	}
}
